CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), platform text NOT NULL CHECK(platform IN ('whatsapp','telegram')), customer_id text NOT NULL, customer_name text NOT NULL DEFAULT '', last_message text NOT NULL DEFAULT '', unread integer NOT NULL DEFAULT 0, bot_paused boolean NOT NULL DEFAULT false, archived boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(platform,customer_id));
GRANT SELECT,UPDATE ON public.conversations TO authenticated;
GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_conversations ON public.conversations FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id), external_id text UNIQUE, direction text NOT NULL CHECK(direction IN ('incoming','outgoing')), text text NOT NULL DEFAULT '', media_url text, status text NOT NULL DEFAULT 'received', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.messages TO authenticated;
GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_messages ON public.messages FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX messages_conversation_time ON public.messages(conversation_id,created_at);
CREATE TABLE public.bot_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid REFERENCES public.conversations(id), kind text NOT NULL DEFAULT 'طلب', details jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'new', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.bot_requests TO authenticated;
GRANT ALL ON public.bot_requests TO service_role;
ALTER TABLE public.bot_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_requests ON public.bot_requests FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.bot_integration (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), key_hash text NOT NULL, reply_url text NOT NULL, last_seen timestamptz);
GRANT ALL ON public.bot_integration TO service_role;
ALTER TABLE public.bot_integration ENABLE ROW LEVEL SECURITY;
ALTER PUBLICATION supabase_realtime ADD TABLE public.conversations,public.messages,public.bot_requests;